parameters.jsonBody:
={
  "model": "gpt-4o-mini",
  "messages": [
    {
      "role": "system",
      "content": "You are a meeting summarizer for Northgate Building Group, a custom home builder in Australia.

Analyze the meeting transcript and return ONLY a valid JSON object (no markdown, no backticks, no explanation before or after) with this exact structure:
{
  "summary": "3-5 bullet points of key discussion items",
  "actionItems": ["task 1 with owner if mentioned"],
  "decisions": ["firm decision 1"],
  "followUp": ["item needing next steps"],
  "projectName": "Best guess of client or project name from the transcript",
  "flag": "green|orange|red",
  "flagReason": "Brief explanation of why this flag"
}

Flag rules:
- RED: Affects structure, requires council approval, major budget impact, or contractual dispute
- ORANGE: Affects critical timeline, requires subcontractor rebooking, or medium budget impact
- GREEN: Standard discussion, minor decisions, no immediate risk

If no action items or decisions, use empty arrays []."
    },
    {
      "role": "user",
      "content": "Meeting Title: {{ $('Extract Transcript').item.json.meetingTitle }}
Date: {{ $('Extract Transcript').item.json.meetingDate }}
Participants: {{ $('Extract Transcript').item.json.participants }}

Transcript:
{{ $('Extract Transcript').item.json.transcript }}"
    }
  ],
  "temperature": 0.2,
  "max_tokens": 2500,
  "response_format": {"type": "json_object"}
}

parameters.jsCode:
const response = $json;
const content = response.choices[0].message.content;
let parsed;

try {
  parsed = JSON.parse(content);
} catch (e) {
  const cleaned = content
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();
  parsed = JSON.parse(cleaned);
}

const joinArray = (val) => {
  if (Array.isArray(val)) return val.join('\n');
  if (typeof val === 'string') return val;
  return '';
};

return [{
  json: {
    summary: parsed.summary || '',
    actionItems: joinArray(parsed.actionItems),
    decisions: joinArray(parsed.decisions),
    followUp: joinArray(parsed.followUp),
    projectName: parsed.projectName || '',
    flag: parsed.flag || 'green',
    flagReason: parsed.flagReason || ''
  }
}];

